insert into public.glossary select * from jsonb_populate_record(null::public.glossary, '{"cle":"tempo","titre":"Tempo (vitesse d''exécution)","contenu":"4 chiffres = phases du mouvement. 1er = excentrique (descente), 2e = pause en bas, 3e = concentrique (poussée), 4e = pause en haut. Ex 3010 : 3s de descente, pas de pause, remontée rapide, pas de pause. X = explosif. Objectif : accumuler du temps sous tension.","created_at":"2026-05-29T17:05:28.160053+00:00"}'::jsonb);
insert into public.glossary select * from jsonb_populate_record(null::public.glossary, '{"cle":"emom","titre":"EMOM (Every Minute On the Minute)","contenu":"Au lieu de 3x à 85-90% avec 5min de repos : 1 rép toutes les minutes à la même intensité, sur X minutes. EMOM1 = 1 rép/min, EMOM2 = 2 rép/min. Permet plus de volume avec meilleure qualité, moins de fatigue. Ladder possible : 1/2/3 puis 3/2/1.","created_at":"2026-05-29T17:05:28.160053+00:00"}'::jsonb);
insert into public.glossary select * from jsonb_populate_record(null::public.glossary, '{"cle":"code_lettre","titre":"Code lettre (ordre & supersets)","contenu":"Les lettres = ordre des exercices. A seul : tu fais A puis ta récup. A1, A2 ensemble : enchaîne les deux puis récup commune après le 2e. Idem B1/B2, C1/C2...","created_at":"2026-05-29T17:05:28.160053+00:00"}'::jsonb);
insert into public.glossary select * from jsonb_populate_record(null::public.glossary, '{"cle":"rpe","titre":"RPE (Rate of Perceived Exertion)","contenu":"Note subjective /10 de l''effort perçu sur l''exercice. 10 = échec, 0 = très facile. Sert à manager l''intensité au fil des semaines. Si trop facile, augmenter la semaine suivante. Si 8-9, ne pas augmenter. Noter sur chaque exo, surtout les gros (en rouge).","created_at":"2026-05-29T17:05:28.160053+00:00"}'::jsonb);
insert into public.intensity_codes select * from jsonb_populate_record(null::public.intensity_codes, '{"code":"epuisant","label":"Mouvements épuisants","description":"Garder 1 répétition de réserve sur chacune des séries. Tu dois t''approcher de l''échec mais pas y aller complètement.","color_hex":"#F4CCCC","created_at":"2026-05-29T17:05:28.160053+00:00"}'::jsonb);
insert into public.intensity_codes select * from jsonb_populate_record(null::public.intensity_codes, '{"code":"semi_epuisant","label":"Mouvements semi-épuisants","description":"Garder 1 à 2 répétitions de réserve sur chaque série et presque échec sur la dernière. S''approcher de l''échec sur la dernière série sans y aller.","color_hex":"#D9EAD3","created_at":"2026-05-29T17:05:28.160053+00:00"}'::jsonb);
insert into public.intensity_codes select * from jsonb_populate_record(null::public.intensity_codes, '{"code":"isolation","label":"Mouvement d''isolation","description":"Objectif : congestionner le muscle. Tu peux aller à l''échec et sentir la brûlure musculaire.","color_hex":"#FFF2CC","created_at":"2026-05-29T17:05:28.160053+00:00"}'::jsonb);
insert into public.intensity_codes select * from jsonb_populate_record(null::public.intensity_codes, '{"code":"prevention","label":"Prévention de blessure","description":"Travail prévention, effacement des déséquilibres + abdos. Facultatif si manque de temps mais important.","color_hex":"#CFE2F3","created_at":"2026-05-29T17:05:28.160053+00:00"}'::jsonb);
insert into public.intensity_codes select * from jsonb_populate_record(null::public.intensity_codes, '{"code":"non_classe","label":"Non classé","description":"À classer par le coach.","color_hex":"#EFEFEF","created_at":"2026-05-29T17:05:28.160053+00:00"}'::jsonb);
insert into public.intensity_codes select * from jsonb_populate_record(null::public.intensity_codes, '{"code":"plyo","label":"Pliométrie","description":"Mouvements de saut et de rebond pour développer la puissance et l''élasticité. Cycle étirement-raccourcissement. Qualité d''exécution > quantité. Repos complet entre les séries — jamais dans la fatigue. Exemples : box jumps, depth jumps, bondissements.","color_hex":"#E07B39","created_at":"2026-06-06T13:13:47.134169+00:00"}'::jsonb);
insert into public.intensity_codes select * from jsonb_populate_record(null::public.intensity_codes, '{"code":"explosif","label":"Explosif","description":"Mouvements de puissance et force explosive","color_hex":"#C8A000","created_at":"2026-06-24T08:07:34.129978+00:00"}'::jsonb);
